bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 60
test -S "$root/deploy/secrets/userbot_verify.sock" || exit 61
spec="$(docker exec -w /opt/videobot "$cid" node --input-type=module -e '
import pg from "pg";import {readFileSync} from "node:fs";
const e=process.env;
const pw=readFileSync("/run/secrets/videobot_db_password","utf8").trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
try{
const q=await db.query("SELECT b.free_message_ids,b.paid_message_id,b.topic_id,l.price_stars FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=l.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND b.status=$1",["sent"]);
if(q.rowCount!==1)process.exitCode=71;
else {
const r=q.rows[0];const ids=[...r.free_message_ids,r.paid_message_id].map(Number);
if(ids.length!==3||ids.some(v=>!Number.isSafeInteger(v)||v<=0))process.exitCode=72;
else console.log(JSON.stringify({ids,thread:Number(r.topic_id),price:Number(r.price_stars)}));
}
}catch{process.exitCode=79;}finally{await db.end()}
')" || exit 62
GACE_SPEC="$spec" python3 -B - <<'PY'
import asyncio,json,os,pathlib,stat,uuid,sys
root=pathlib.Path("/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot")
socket=root/"deploy/secrets/userbot_verify.sock"
if not socket.is_socket() or socket.stat().st_uid!=os.getuid() or stat.S_IMODE(socket.stat().st_mode)!=0o600:sys.exit(63)
info=json.loads(os.environ["GACE_SPEC"])
if set(info)!={"ids","thread","price"}:sys.exit(64)
if not (isinstance(info["ids"],list) and len(info["ids"])==3 and len(set(info["ids"]))==3):sys.exit(65)
async def call(ids,thread):
    reader,writer=await asyncio.wait_for(asyncio.open_unix_connection(str(socket)),5)
    try:
        key=uuid.uuid4().hex
        req={"request_id":key,"action":"video_sale_readback","chat_id":-1002373696859,
             "thread_id":thread,"message_ids":ids}
        writer.write((json.dumps(req)+"\n").encode());await writer.drain()
        data=await asyncio.wait_for(reader.readline(),40)
        result=json.loads(data)
        if result.get("status")!="PASS" or result.get("request_id")!=key:raise RuntimeError("READBACK_RESULT_INVALID")
        return result
    finally:
        writer.close();await writer.wait_closed()
try:
    new=asyncio.run(call(info["ids"],info["thread"]))
    print("USERBOT_NEW_FREE_NATIVE_ALBUM="+str(new.get("free_album_grouped")))
    print("USERBOT_NEW_NATIVE_PAID_MEDIA="+str(new.get("paid_media_native")))
    print("USERBOT_NEW_TOPIC_CORRECT="+str(new.get("target_topic_confirmed")))
    if not new.get("free_album_grouped"):sys.exit(71)
    if not new.get("paid_media_native"):sys.exit(72)
    if new.get("paid_stars")!=info["price"]:sys.exit(73)
    if not new.get("target_topic_confirmed"):sys.exit(74)
    print("USERBOT_TELEGRAM_NATIVE_VIDEO_TRIPLE=PASS")
except Exception:
    sys.exit(78)
PY
